CREATE TABLE rv_job (id BYTEA PRIMARY KEY, queue VARCHAR(64) NOT NULL, kind VARCHAR(64) NOT NULL, payload BYTEA NOT NULL, idempotency_key VARCHAR(128) NULL, state SMALLINT NOT NULL CHECK (state BETWEEN 0 AND 3), attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0), max_attempts INTEGER NOT NULL CHECK (max_attempts BETWEEN 1 AND 100), run_at TIMESTAMPTZ NOT NULL, lease_token BYTEA NULL, lease_expires_at TIMESTAMPTZ NULL, last_failure SMALLINT NULL CHECK (last_failure BETWEEN 1 AND 5), trace_parent VARCHAR(55) NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, completed_at TIMESTAMPTZ NULL);
